title_rewrites = {
    "square-multiply": ("Esponenziazione binaria (square-and-multiply)", "Square-and-multiply exponentiation"),
    "double-add": ("Raddoppio e addizione (double-and-add)", "Double-and-add multiplication"),
    "vernam": ("Cifrario di Vernam e chiave monouso", "Vernam cipher and one-time pad"),
    "lenstra": ("Metodo di Lenstra (ECM)", "Lenstra elliptic-curve method (ECM)"),
    "hash": ("Funzioni hash e collisioni", "Hash functions and collisions"),
}

for path in catalogues:
    data = json.loads(path.read_text())
    for concept in data["concepts"]:
        if concept["id"] in title_rewrites:
            concept["title"], concept["titleEN"] = title_rewrites[concept["id"]]
        if concept["id"] in summary_rewrites:
            concept["summary"], concept["summaryEN"] = summary_rewrites[concept["id"]]
        changes = rewrites.get(concept["id"])
        if changes is None:
            changes = {}
        for key in ("summary", "summaryEN"):
            if key in changes:
                concept[key] = changes[key]
        for block in concept["blocks"]:
            pair = changes.get(block["id"])
            if pair:
                block["text"], block["textEN"] = pair
            if concept["id"] == "modular-arithmetic" and block["id"] == "learn-0":
                block["text"] = block["text"].replace(
                    r"perciò aggiungere \(m\) ore non cambia la posizione.",
                    "perciò compiere un giro intero lascia invariata la posizione.",
                )
                block["textEN"] = block["textEN"].replace(
                    r"so adding \(m\) hours does not change its position.",
                    "so completing one full turn leaves its position unchanged.",
                )
            for key in ("text", "textEN"):
                block[key] = block[key].replace("moduloN", r"modulo \(N\)")
                block[key] = block[key].replace("divideN", r"divide \(N\)")
                block[key] = block[key].replace("dividesN", r"divides \(N\)")
                block[key] = block[key].replace("è-1", r"-1")
                block[key] = block[key].replace("multipli diN", r"multipli di \(N\)")
                block[key] = block[key].replace("multiples ofN", r"multiples of \(N\)")
                block[key] = block[key].replace(
                    r"\(e(a^{-1})^{p^{r}}=a^{-1}\)",
                    r"e \((a^{-1})^{p^{r}}=a^{-1}\)",
                )
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n")
